const selectFieldsForRunAll = `-- name: SelectFieldsForRunAll :many
SELECT x.id::text AS id
FROM fields x
WHERE x.company_id = $1 AND x.farm_id = $2 AND x.deleted_at IS NULL
ORDER BY x.block NULLS FIRST, x.name, x.id
`

type SelectFieldsForRunAllParams struct {
	CompanyID string
	FarmID    string
}

func (q *Queries) SelectFieldsForRunAll(ctx context.Context, arg SelectFieldsForRunAllParams) ([]string, error) {
	rows, err := q.db.Query(ctx, selectFieldsForRunAll, arg.CompanyID, arg.FarmID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []string
	for rows.Next() {
		var id string
		if err := rows.Scan(&id); err != nil {
			return nil, err
		}
		items = append(items, id)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const selectFieldsForRunMissing = `-- name: SelectFieldsForRunMissing :many
SELECT x.id::text AS id
FROM fields x
LEFT JOIN field_terrain t ON t.company_id = x.company_id AND t.field_id = x.id
WHERE x.company_id = $1 AND x.farm_id = $2 AND x.deleted_at IS NULL
  AND (t.id IS NULL OR t.status IN ('pending', 'failed'))
ORDER BY x.block NULLS FIRST, x.name, x.id
`

type SelectFieldsForRunMissingParams struct {
	CompanyID string
	FarmID    string
}

// Sem linha, pendentes ou com falha.
func (q *Queries) SelectFieldsForRunMissing(ctx context.Context, arg SelectFieldsForRunMissingParams) ([]string, error) {
	rows, err := q.db.Query(ctx, selectFieldsForRunMissing, arg.CompanyID, arg.FarmID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []string
	for rows.Next() {
		var id string
		if err := rows.Scan(&id); err != nil {
			return nil, err
		}
		items = append(items, id)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const upsertTerrainAdjustment = `-- name: UpsertTerrainAdjustment :execrows
INSERT INTO field_terrain_adjustments (company_id, field_id, origin, slope_mean_pct, slope_max_pct, position,
                                       justification, adjusted_by, adjusted_at)
SELECT x.company_id, x.id, $1, $2::float8, $3::float8,
       $4, $5, $6, $7::timestamptz
FROM fields x
WHERE x.company_id = $8 AND x.farm_id = $9 AND x.id = $10
  AND x.deleted_at IS NULL
ON CONFLICT (company_id, field_id) DO UPDATE
SET origin = EXCLUDED.origin, slope_mean_pct = EXCLUDED.slope_mean_pct, slope_max_pct = EXCLUDED.slope_max_pct,
    position = EXCLUDED.position, justification = EXCLUDED.justification, adjusted_by = EXCLUDED.adjusted_by,
    adjusted_at = EXCLUDED.adjusted_at, version = field_terrain_adjustments.version + 1
`

type UpsertTerrainAdjustmentParams struct {
	Origin        string
	SlopeMeanPct  float64
	SlopeMaxPct   float64
	Position      string
	Justification string
	AdjustedBy    string
	AdjustedAt    time.Time
	CompanyID     string
	FarmID        string
	FieldID       string
}

// Ajuste manual: um por talhão. A busca em fields garante empresa, fazenda e talhão não removido
// (0 linhas = não encontrado). O autor e a data são os do ajuste, não de quem regrava.
func (q *Queries) UpsertTerrainAdjustment(ctx context.Context, arg UpsertTerrainAdjustmentParams) (int64, error) {
	result, err := q.db.Exec(ctx, upsertTerrainAdjustment,
		arg.Origin,
		arg.SlopeMeanPct,
		arg.SlopeMaxPct,
		arg.Position,
		arg.Justification,
		arg.AdjustedBy,
		arg.AdjustedAt,
		arg.CompanyID,
		arg.FarmID,
		arg.FieldID,
	)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}
